Construction
let logs: Directory := create Directory.make("var/logs")
let same: Directory := create Directory.from_path(create Path.make("var/logs"))

Construction
let reader: Text_File := create Text_File.open_read(create Path.make("in.txt"))
let writer: Text_File := create Text_File.open_write(create Path.make("out.txt"))
let log:    Text_File := create Text_File.open_append(create Path.make("app.log"))A file is opened by its constructor; the mode is fixed for the life of the handle.

Construction
let reader: Binary_File := create Binary_File.open_read(create Path.make("image.png"))
let writer: Binary_File := create Binary_File.open_write(create Path.make("out.bin"))
let log:    Binary_File := create Binary_File.open_append(create Path.make("events.bin"))

Construction
let words: Regex := create Regex.compile("[a-z]+")
let any_case: Regex := create Regex.compile_with_flags("[a-z]+", "i")An invalid pattern raises a runtime error at construction, so a Regex value always holds a usable pattern.

Construction
let timeout: Duration := create Duration.seconds(30)
let sprint: Duration := create Duration.weeks(2)Each constructor names its unit. Durations may be negative.

Construction
let now: Date_Time := create Date_Time.now()
let launch: Date_Time := create Date_Time.make(2026, 3, 13, 10, 30, 0)
let parsed: Date_Time := create Date_Time.parse_iso("2026-03-13T10:30:00Z")
let epoch: Date_Time := create Date_Time.from_epoch_millis(0)intern time/Date_Time also loads time/Duration.
